import hashlib, json, re
from html.parser import HTMLParser
from pathlib import Path

class VisibleText(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts = []
        self.hidden = None
    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden = tag
    def handle_endtag(self, tag):
        if tag == self.hidden:
            self.hidden = None
    def handle_data(self, data):
        if self.hidden is None:
            text = ' '.join(data.split())
            if text:
                self.parts.append(text)

root = Path('products/services/wordpress-migration-paid-pilot')
source = root / 'raw/astra-original-listing.html'
raw = source.read_bytes()
digest = hashlib.sha256(raw).hexdigest()
assert digest == 'd30015f76109eee1186bb68d4216695a33cb806ec6dedcf8ab881b74a2238fb7'
page = VisibleText()
page.feed(raw.decode('utf-8', errors='replace'))
terms = re.compile(r'DevOps Engineer|full.time|part.time|employment|migrat|apply for|application|contract|deliverable', re.I)
quotes = list(dict.fromkeys(part for part in page.parts if terms.search(part)))
report = {'source': 'https://jobs.wordpress.net/job/astra-devops-engineer-wordpress-hosting/', 'source_sha256': digest, 'source_receipt': 'TASK-179547696100', 'visible_text_matches': [part[:500] for part in quotes[:30]], 'scope': 'Visible-text excerpts from one original listing. Excerpts support review of role, migration responsibilities and application terms. No application or buyer response occurred.'}
(root / 'astra-role-evidence.json').write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
